INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-199', '199', '5-star-hotel-opportunity-london', '5-Star Hotel Opportunity — London', 'United Kingdom', 'casino-hotel', '£450 Million', 'draft', 'pending', 'OPPORTUNITY', '5-star hotel investment opportunity in London.', '<p><strong>London • September 2026 Availability</strong></p><p>A second premium <strong>5-star hotel investment opportunity in London</strong>, becoming available for sale in <strong>September 2026</strong>.</p><p>This represents an opportunity to acquire a substantial luxury hospitality asset in the London market, suitable for experienced investors, hotel operators, and property investment groups.</p><p><strong>Availability:</strong> September 2026</p><p><strong>Price:</strong> £450 Million</p><p><em>Full property details, supporting documentation, and viewing information are available to qualified buyers upon request.</em></p>', 'September 2026', '["5-star hotel investment opportunity in London.","Becoming available for sale in September 2026.","Premium hospitality investment opportunity for experienced investors, hotel operators and property investment groups.","International buyer and operator interest welcome, subject to qualification."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-198', '198', '5-star-hotel-opportunity-london-2', '5-Star Hotel Opportunity — London', 'United Kingdom', 'casino-hotel', '£400 Million', 'draft', 'pending', 'OPPORTUNITY', '5-star hotel with approximately 300 rooms.', '<p><strong>London • Listed 28 August 2026</strong></p><p>A prestigious <strong>5-star hotel opportunity in London</strong>, featuring approximately <strong>300 rooms</strong> and offering a significant investment opportunity in one of the world’s leading hospitality markets.</p><p><strong>Listed:</strong> 28 August 2026</p><p><strong>Price:</strong> £400 Million</p><p><em>Further property information, due diligence documentation, and viewing arrangements are available upon qualified buyer enquiry.</em></p>', '', '["5-star hotel with approximately 300 rooms.","Prime London investment opportunity in one of the world’s leading hospitality markets.","Suitable for institutional investors, hospitality groups and international developers.","High-value asset with significant long-term potential."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-197', '197', 'egypt-development-340-apartments-casino-planning', 'Egypt Development — 340 Apartments + Casino Planning', 'Egypt', 'casino', 'Price on Request', 'draft', 'pending', 'OPPORTUNITY', '340 apartments across a three-level development.', '<p><strong>Additional Development Potential</strong></p><p>The property comprises a three-level block of 340 apartments. The red-brick exterior is substantially completed, while the interior fit-out and windows remain to be completed by the new owner/developer.</p><p>The development includes planning provision for a casino, proposed to be installed on the land within the gardens adjacent to the development. There is also provision for a large swimming pool, with completion to be undertaken as part of the overall development.</p><p><strong>Availability and commercial terms should be confirmed directly with Casinos of Mayfair.</strong></p>', '', '["340 apartments across a three-level development.","Red-brick exterior substantially completed; interior fit-out and windows remain to be completed by the new owner/developer.","Planning provision for a casino on the land within the gardens adjacent to the development.","Provision for a large swimming pool, with final completion to be undertaken by the new owner/developer."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-196', '196', '21st-may-no-196-rare-opportunity', '21st May No 196(Rare Opportunity)', 'United Kingdom', 'casino', '£750 million', 'draft', 'pending', 'OPPORTUNITY', 'Central London This is a rare opportunity to acquire a prestigious 5-star deluxe hotel in the heart of central London.', '<p>Central London</p><p>This is a rare opportunity to acquire a prestigious 5-star deluxe hotel in the heart of central London.</p><p>This exquisite hotel features 350 elegantly designed deluxe rooms, a gourmet restaurant, and a heated indoor swimming pool. Highly popular for short stays of up to 14 days, it enjoys a prime location within walking distance of major attractions, theatres, casinos, cinemas, and top-tier restaurants.</p><p>The property is available for £750 million, with a unique financing structure that allows for acquisition with an initial payment of just £450 million. A £300 million loan, secured at an exceptionally low interest rate of 3.5% from a major bank, is included in the purchase price and will be transferred to the new owner, enabling repayment through standard trading revenue.</p>', '', '["Central London This is a rare opportunity to acquire a prestigious 5-star deluxe hotel in the heart of central London.","This exquisite hotel features 350 elegantly designed deluxe rooms, a gourmet restaurant, and a heated indoor swimming pool.","Highly popular for short stays of up to 14 days, it enjoys a prime location within walking distance of major attractions, theatres, casinos, cinemas, and top-tier restaurants."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
