INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-193', '193', '4th-january-listing-193', '4th January Listing 193', 'Spain', 'casino', '240m euros', 'draft', 'pending', 'OPPORTUNITY', 'Luxury 5 star hotel for sale in Madrid Spain This beautiful hotel is one of the best hotels in Europe.', '<p>Luxury 5 star hotel for sale in Madrid Spain</p><p>This beautiful hotel is one of the best hotels in Europe. impeccable service. Gastronomy restaurant, fabulous Spa with heated swimming pool. Gymnasium. Convention centre. Wedding specialists with a 1000 m2 of incredible gardens in one of the most elegant commercial and residential areas of Madrid and only 10 minutes by car to the airport Madrid great value price 240m euros.</p><p>An awesome price offer at <strong>240m Euros.</strong></p>', '', '["Luxury 5 star hotel for sale in Madrid Spain This beautiful hotel is one of the best hotels in Europe.","Gastronomy restaurant, fabulous Spa with heated swimming pool."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-192', '192', '4th-october-listing-192', '4th October Listing 192', NULL, 'casino', '$155m', 'draft', 'pending', 'OPPORTUNITY', 'North Africa This very luxurious international brand 5 star hotel and casino was recently refurbished and has set a president of Modern and Antique furnishing working so well together, With 240 elegant suites is certainly a resort for those looking to be treated like There are two excellent restaurants I personally can recommend their 16 oz Sirloin steaks.', '<p>North Africa</p><p>This very luxurious international brand 5 star hotel and casino was recently refurbished and has set a president of Modern and Antique furnishing working so well together, With 240 elegant suites is certainly a resort for those looking to be treated like There are two excellent restaurants I personally can recommend their 16 oz Sirloin steaks.</p><p>A well equipped gymnasium, Cool Entertainment bars, The largest and busiest casino in the whole of the Africa continent, with quality slots, high jackpots, Manic roulette tables, yearly International Tournament of Poker,</p><p>Every aspect of this very Grand hotel and casino demonstrates good quality and wanting to come back again soon feeling, all this and set in the beautiful tropical gardens surrounding a splendid swimming pool, with fantastic Ocean views,</p><p>An awesome cash price offer at <strong>$155m dollars.</strong></p><p> Full details with signed NDA,</p>', '', '["North Africa This very luxurious international brand 5 star hotel and casino was recently refurbished and has set a president of Modern and Antique furnishing working so well together, With 240 elegant suites is certainly a resort for those looking to be treated like There are two excellent restaurants I personally can recommend their 16 oz Sirloin steaks.","A well equipped gymnasium, Cool Entertainment bars, The largest and busiest casino in the whole of the Africa continent, with quality slots, high jackpots, Manic roulette tables, yearly International Tournament of Poker, Every aspect of this very Grand hotel and casino demonstrates good quality and wanting to come back again soon feeling, all this and set in the beautiful tropical gardens surrounding a splendid swimming pool, with fantastic Ocean views, An awesome cash price offer at $155m dollars."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-191', '191', '15th-june-listing-191', '15th June Listing 191', 'France', 'casino', '85m Euros', 'draft', 'pending', 'OPPORTUNITY', 'Riveria France Brand New 4 star hotel on the beach with 90 luxury rooms all with sea views.', '<p>Riveria France</p><p>Brand New 4 star hotel on the beach with 90 luxury rooms all with sea views. with a new casino being installed into this luxury hotel on the French riveria. The hotel has just opened. The casino will have all popular casinos games Roulette. Blackjack. Plus 200 slot machines will open in two months. This is a fantastic investment to purchase the freehold property With full management from a famous French family hotel group.who is offering this great opportunity to lease the hotel for 10 years renewable rental of 5% for hotel and 25% of revenue from the casino.</p><p>Total investment 85m Euros. </p><p>Estimated annual returns 6-8m Euros</p>', '', '["Riveria France Brand New 4 star hotel on the beach with 90 luxury rooms all with sea views.","with a new casino being installed into this luxury hotel on the French riveria.","The casino will have all popular casinos games Roulette."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-190', '190', '2nd-february-listing-190', '2nd February Listing 190', 'United States', 'casino', '$ 1,500.000', 'draft', 'pending', 'OPPORTUNITY', 'Texas USA The property is comprised of uninterrupted linear 820 ft of water front in a protected cove, with 22 boat slips, 10 PWC ramps, and a private boat ramp and a 3 boat boathouse.', '<p>Texas USA</p><p>The property is comprised of uninterrupted linear 820 ft of water front in a protected cove, with 22 boat slips, 10 PWC ramps, and a private boat ramp and a 3 boat boathouse. The Hotel’s 2 buildings feature 13 rooms – 4 of with are 1000 – 1600 sqft apartments with multiple bedrooms and full kitchens. The Hotel can accommodate currently 62 guests. Between the 2 buildings is a 50.000 gal 8 ft deep pool. The waterfront Restaurant has outside seating for approx. 80 guests under 2 covered patios, as well as inside seating for approx. 35 guests. It features a full bar with 2 sit-at bar counters. A richly stocked “Wine Cave” compliments the Restaurant/Bar. The Convenience Store &amp; Marina Office has a walk-in beverage cooler, a beer &amp; wine package license, the boat rental desk as well as the office and retail space primarily for marine related items. The boat gas station with 4 full service pumps is also under roof with 3 boat docking bays. It is served by 1 above ground tank (2000 gal), a tanker storage truck (2800 gal) and a tanker storage truck (2000 gal) A smaller workshop and the 1600 sqft boat detailing shop and a big parking lot are at the same level. There are also 2 boat storage buildings for dry storage of customer’s boats with a capacity of 16 storage boats. On top is the boat repair facility with 4 fully equipped and tooled service/repair bays, parts room &amp; office. Additionally, there is the Manager’s house (3 BR, 3 baths) as well as a Staff House (3 BR, 1.5 baths) within 200 yards available. The septic system for the entire property has been completely renewed and LCRA approved in 2017 and is under contracted maintenance. 2 Solar power systems with 12 MW &amp; 11 MW respectively, are operating under net-metering rules. All areas are fully operating including a boat rental fleet of 14 boats and 12 PWC’s as well as work and tow boats. There are also 3.5 unimproved lots next to the property available as well as 9 unimproved lots neighboring City Hall. Sales in 2020 were $ 1,500.000 EBITDA 2020 was $ 762.400</p><p>Price : $6.3 M</p>', '', '["Texas USA The property is comprised of uninterrupted linear 820 ft of water front in a protected cove, with 22 boat slips, 10 PWC ramps, and a private boat ramp and a 3 boat boathouse.","The Hotel’s 2 buildings feature 13 rooms – 4 of with are 1000 – 1600 sqft apartments with multiple bedrooms and full kitchens.","The Hotel can accommodate currently 62 guests."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
