INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-185', '185', 'listing-185-portegual', 'Listing 185 (Portegual)', NULL, 'casino', '$149m', 'draft', 'pending', 'OPPORTUNITY', '5 Star Beach Resort & Casino 90 Rooms +60 Suites+40 Premium Suites + 16 Apartments 2 Spas, 2 Restaurants + 2 Swimming Pools The total area of 4000 Sq.mtrs 14 Floor Hotel Casino great slot action with 200 Slot machines + 16 Gaming Tables Dazzling Views of Marina & the Atlantic Conference hall for 950 people Pool, Bar, Spa & Restaurant The Apartments consist of 4 X 2 Beds + 12 X 3 Beds.', '<p>5 Star Beach Resort &amp; Casino </p><p>90 Rooms +60 Suites+40 Premium Suites + 16 Apartments</p><p>2 Spas, 2 Restaurants + 2 Swimming Pools</p><p>The total area of 4000 Sq.mtrs</p><p>14 Floor Hotel</p><p>Casino great slot action with 200 Slot machines + 16 Gaming Tables</p><p>Dazzling Views of Marina &amp; the Atlantic</p><p>Conference hall for 950 people</p><p>Pool, Bar, Spa &amp; Restaurant</p><p>The Apartments consist of 4 X 2 Beds + 12 X 3 Beds.</p><p>Asking price= $149m dollars 15th November 2020</p>', '', '["5 Star Beach Resort & Casino 90 Rooms +60 Suites+40 Premium Suites + 16 Apartments 2 Spas, 2 Restaurants + 2 Swimming Pools The total area of 4000 Sq.mtrs 14 Floor Hotel Casino great slot action with 200 Slot machines + 16 Gaming Tables Dazzling Views of Marina & the Atlantic Conference hall for 950 people Pool, Bar, Spa & Restaurant The Apartments consist of 4 X 2 Beds + 12 X 3 Beds.","Asking price= $149m dollars 15th November 2020"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_