INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-184', '184', 'listing-184-croatia', 'Listing 184 (Croatia)', 'Croatia', 'casino', '19.000.000 Euros', 'draft', 'pending', 'OPPORTUNITY', 'The best casino in the country of Croatia.with a plot of land available to build a 60 room hotel.', '<p>The best casino in the country of Croatia.with a plot of land available to build a 60 room hotel. but I feel it is not necessary to build a hotel. we could build an annexe with a live gaming casino studio for internet gaming</p><p>my reason for this information is that there is already a 5-star hotel with 600 rooms with no casino for its guests and our casino is built on the land previously owned by the hotel,</p><p>the casino has parking for 300 cars with car jockey parking, all the favourite casino games are played and the casino property has been operating for 9 years with good profits but the owner is looking to retire, hence the very interesting price for the complete business, casino building, land, and casino licence,</p><p>for only 19.000.000 Euros</p><p>Full information is available after  CA, NDA is signed, 18th October 2020</p>', '', '["The best casino in the country of Croatia.with a plot of land available to build a 60 room hotel.","but I feel it is not necessary to build a hotel.","we could build an annexe with a live gaming casino studio for internet gaming my reason for this information is that there is already a 5-star hotel with 600 rooms with no casino for its guests and our casino is built on the land previously owned by the hotel, the casino has parking for 300 cars with car jockey parking, all the favourite casino games are played and the casino property has been operating for 9 years with good profits but the owner is looking to retire, hence the very interesting price for the complete business, casino building, land, and casino licence, for only 19.000.000 Euros Full information is available after CA, NDA is signed, 18th October 2020"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
