INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-76', '76', 'listing-76-costa-rica-now-sold', 'Listing 76 ( Costa Rica, now sold )', 'Costa Rica', 'casino', '145,000 euros', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Update 10th May Casino closed management problems, Could be open same day with all staff in place,open to offers above 145,000 euros to move Great opportunity to get your own operating casino Very Smart stand-alone Casino with Live gaming tables, slot machines plus 8 seaters touch bet roulette property on lease TotalSale price is 400,000 euros payable over 3 years, now Sold Properties listings from Number 1 to 75 are listed below, please note many of these properties have been sold or taken off the market but there are several still available listed by country, the ones sold are still visible USA USA/Caribbean Casinos for sale Starting with listing number 1 Information Casinos of Mayfair are unable to reveal full details of the properties before receipt of signed confidentiality and non-disclosure, Casino Owners please note Fee’s and commissions are paid only after completion of the sale by Casinos of Mayfair, The scale of fees are listed at the end of USA listings below Due to the confidential nature of the casino Industry & for the Security of the Casino Property, Photographs of Live Casinos for sale cannot be Shown on the Internet.', '<p><strong>Update 10th May Casino closed management problems, Could be open same day with all staff in place,open to offers above 145,000 euros to move Great opportunity to get your own operating casino Very Smart stand-alone Casino with Live gaming tables, slot machines plus 8 seaters touch bet roulette property on lease TotalSale price is 400,000 euros payable over 3 years, now Sold</strong></p><p>Properties listings from Number 1 to 75 are listed below, please note many of these properties have been sold or taken off the market but there are several still available listed by country, the ones sold are still visible USA USA/Caribbean Casinos for sale Starting with listing number 1 Information <strong>Casinos of Mayfair</strong></p><p><strong>are unable to reveal full details of the properties before receipt of signed</strong> <strong>confidentiality and non-disclosure,</strong> <strong>Casino Owners please note Fee’s and commissions are paid only after completion of the sale by Casinos of Mayfair,</strong> <strong>The scale of </strong>fees<strong> are listed at the end of USA listings below</strong></p><p>Due to the confidential nature of the casino Industry &amp; for the Security of the Casino Property, Photographs of Live Casinos for sale cannot be Shown on the Internet.</p><p>(Listing numbers of the properties are in Brackets and the countries are listed in alphabetical order where the casino is located below please be advised many of these properties below have been sold or withdrawn but are updated to display this fact.</p>', '', '["Update 10th May Casino closed management problems, Could be open same day with all staff in place,open to offers above 145,000 euros to move Great opportunity to get your own operating casino Very Smart stand-alone Casino with Live gaming tables, slot machines plus 8 seaters touch bet roulette property on lease TotalSale price is 400,000 euros payable over 3 years, now Sold Properties listings from Number 1 to 75 are listed below, please note many of these properties have been sold or taken off the market but there are several still available listed by country, the ones sold are still visible USA USA/Caribbean Casinos for sale Starting with listing number 1 Information Casinos of Mayfair are unable to reveal full details of the properties before receipt of signed confidentiality and non-disclosure, Casino Owners please note Fee’s and commissions are paid only after completion of the sale by Casinos of Mayfair, The scale of fees are listed at the end of USA listings below Due to the confidential nature of the casino Industry & for the Security of the Casino Property, Photographs of Live Casinos for sale cannot be Shown on the Internet.","(Listing numbers of the properties are in Brackets and the countries are listed in alphabetical order where the casino is located below please be advised many of these properties below have been sold or withdrawn but are updated to display this fact."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-75', '75', 'listing-75', 'Listing 75', 'United States', 'casino', '$32m', 'draft', 'pending', 'OPPORTUNITY', 'Update JANUARY 2017 Las Vegas offered a vacant lot of 40 Acres with full permits planning and codes, to build a 6,000 room+ Hotel and Casino resort, 2008 price was $32m an Acre, today’s Price $14m an Acre will accept $500m as is Great opportunity Casinos of Mayfair WORLDS LARGEST CASINO BROKERAGE Sales & Management Consultants to the Casino Industry Established in London since 1994 Company Profile Casinos of Mayfair was Registered in London, England, in June 1994.and has now become the largest casino broker in the world.', '<p>Update JANUARY 2017 Las Vegas offered a vacant lot of 40 Acres with full permits planning and codes, to build a 6,000 room+ Hotel and Casino resort, 2008 price was $32m an Acre, today’s Price $14m an Acre will accept $500m as is Great opportunity Casinos of Mayfair WORLDS LARGEST CASINO BROKERAGE</p><p><strong>Sales &amp; Management Consultants to the Casino Industry Established in London since 1994</strong></p><p><strong>Company Profile</strong></p><p><strong>Casinos of Mayfair was Registered in London, England, in June 1994.and has now become the largest casino broker in the world. Casinos of Mayfair is a specialist brokerage company only for the sale and purchase of Casinos throughout the world. As the demand for gaming is increasing throughout America &amp; the World, Casinos of Mayfair are looking to open an office soon in the Capital of Gaming Las Vegas. opened 2004</strong></p><p>Casinos of Mayfair is a confidential intermediate between the Seller and Buyer. Casinos of Mayfair currently has listings of over 50 Casinos for Sale from under $1m to over $1 Billion Worldwide, with an extensive portfolio of buyers and investors.</p><p>Casino Owners, please note our commission fee is <strong>A </strong>one-off<strong> fee paid only on successful completion of Sale</strong> Our commission fees vary between.3% &amp; 0.50%, depending on the price of the property. Example,3% up to $2m 2.5% — $20m,  2.% — $30m, 1.5% — $50m 1% — $500m, </p><p>0.50% — no limit, </p><p>Casinos of Mayfair offers a comprehensive consultancy to the gaming industry. From concept to a turnkey operation with full Casino Management service, Casinos of Mayfair licensed staff of 5 manager/consultants with the management skills and 140 years of combined experience in the casino industry to assist with all essential requirements.</p><p>Casinos of Mayfair also provides contacts for finance and Joint Venture partners. Staff recruitments are increasing demand from existing clients. Casinos of Mayfair can provide the highest quality of employees from their registered applicant’s file.</p><p>Casinos of Mayfair are always looking for casinos for sale to satisfy their client’s demands, if you know of a casino that may be for sale please contact us, a finders fee will be paid within 24 hours of the sale of this casino to one of our clients introduced to the casino owners,</p><p>Casinos of Mayfair International Ltd guarantees it will conduct all dealings with absolute discretion and confidentiality now Advertising section now available Links to websites of interest to the casino industry</p><p>- [www.gbgb.org.uk](https://web.archive.org/web/20250711083801/http://www.gbgb.org.uk/) - [www.gamblingcompliance.com](https://web.archive.org/web/20250711083801/http://www.gamblingcompliance.com/) - [www.americangaming.org](https://web.archive.org/web/20250711083801/https://www.americangaming.org/) - [www.gamblingcommission.gov.uk](https://web.archive.org/web/20250711083801/http://www.gamblingcommission.gov.uk/) - [www.gamcare.org.uk](https://web.archive.org/web/20250711083801/http://www.gamcare.org.uk/) - [www.cammegh.com](https://web.archive.org/web/20250711083801/http://www.cammegh.com/) - [www.abbiati.com](https://web.archive.org/web/20250711083801/http://www.www.abbiati.com/) - [www.gamingcompliance.com](https://web.archive.org/web/20250711083801/http://gamingcompliance.com/)</p>', '', '["Update JANUARY 2017 Las Vegas offered a vacant lot of 40 Acres with full permits planning and codes, to build a 6,000 room+ Hotel and Casino resort, 2008 price was $32m an Acre, today’s Price $14m an Acre will accept $500m as is Great opportunity Casinos of Mayfair WORLDS LARGEST CASINO BROKERAGE Sales & Management Consultants to the Casino Industry Established in London since 1994 Company Profile Casinos of Mayfair was Registered in London, England, in June 1994.and has now become the largest casino broker in the world.","Casinos of Mayfair is a specialist brokerage company only for the sale and purchase of Casinos throughout the world.","As the demand for gaming is increasing throughout America & the World, Casinos of Mayfair are looking to open an office soon in the Capital of Gaming Las Vegas."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
