INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-68', '68', 'listing-68', 'Listing 68', 'United States', 'casino', '$100m', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'update June 2014 Now Sold Las Vegas This is a great opportunity to buy a Famous operating Hotel Casino with over 2000 rooms on the strip with an approx refurb of $100m needed.but a loan is available for this refurb, but not for the buy out this is a cash deal, Price $125m.', '<p>update June 2014 Now Sold Las Vegas This is a great opportunity to buy a Famous operating Hotel Casino with over 2000 rooms on the strip with an approx refurb of $100m needed.but a loan is available for this refurb, but not for the buy out this is a cash deal,</p><p>Price $125m. Proof of funds -Required Now Sold</p>', '', '["update June 2014 Now Sold Las Vegas This is a great opportunity to buy a Famous operating Hotel Casino with over 2000 rooms on the strip with an approx refurb of $100m needed.but a loan is available for this refurb, but not for the buy out this is a cash deal, Price $125m."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-67', '67', 'listing-67', 'Listing 67', 'United States', 'casino', '$2m', 'draft', 'pending', 'OPPORTUNITY', 'Updated January 2017 Las VegasThis two casino opportunity one has a small 50 bedroom hotel and is one of the older type properties but is used by the locals and special poker groups, Both are in need of refurb and quoted costs are approx $15m-$20m or $ 35m for both, to bring them back to their former glory and a loan is available for these refurbishment costs at 4.5% interest, The casinos are making a small nett profit of over $2m net, but this profit will receive a large boost to this bottom line after refurb has finished, This information will be released to the potential buyer who provides POF, Price the owner is asking is $60m, for the two properties, will not split', '<p>Updated January 2017 Las VegasThis two casino opportunity one has a small 50 bedroom hotel and is one of the older type properties but is used by the locals and special poker groups, Both are in need of refurb and quoted costs are approx $15m-$20m or $ 35m for both, to bring them back to their former glory and a loan is available for these refurbishment costs at 4.5% interest, The casinos are making a small nett profit of over $2m net, but this profit will receive a large boost to this bottom line after refurb has finished, This information will be released to the potential buyer who provides POF, Price the owner is asking is $60m, for the two properties, will not split</p>', '', '["Updated January 2017 Las VegasThis two casino opportunity one has a small 50 bedroom hotel and is one of the older type properties but is used by the locals and special poker groups, Both are in need of refurb and quoted costs are approx $15m-$20m or $ 35m for both, to bring them back to their former glory and a loan is available for these refurbishment costs at 4.5% interest, The casinos are making a small nett profit of over $2m net, but this profit will receive a large boost to this bottom line after refurb has finished, This information will be released to the potential buyer who provides POF, Price the owner is asking is $60m, for the two properties, will not split"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-66', '66', 'listing-66', 'Listing 66', 'United States', 'casino', '$220m', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Updated December 2014 This property has now been sold Nevada Las Vegas Great Opportunity to buy an off-strip 2500+ room hotel/casino resort a CA,NDA will get you the details of the property, POF will get you the financial, and a meeting with the owners to discuss this very reduced price of $220m Correct $220m no debts, but will need approx $100=$150m refurbishment, funding available in total 80% approx $200m or a possible JV is available with a major public company, Now Sold', '<p>Updated December 2014 This property has now been sold Nevada Las Vegas Great Opportunity to buy an off-strip 2500+ room hotel/casino resort  a CA,NDA will get you the details of the property, POF will get you the financial, and a meeting with the owners to discuss this very reduced price of $220m Correct $220m no debts, but will need approx $100=$150m refurbishment, funding available in total 80% approx $200m or a possible JV is available with a major public company, Now Sold</p>', '', '["Updated December 2014 This property has now been sold Nevada Las Vegas Great Opportunity to buy an off-strip 2500+ room hotel/casino resort a CA,NDA will get you the details of the property, POF will get you the financial, and a meeting with the owners to discuss this very reduced price of $220m Correct $220m no debts, but will need approx $100=$150m refurbishment, funding available in total 80% approx $200m or a possible JV is available with a major public company, Now Sold"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.pric