INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-47', '47', 'listing-47', 'Listing 47', 'Macau', 'casino', '$360m', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Update 24 March 2015 the last of the 5 casinos has been sold today, Macau see listing below for each hotel/casino price,but the price of the 1 remaining casino hotel for sale is now $360,000,000 US operating with profit in Macau Price $360,000,000, new funding of 75% available on this last property with Management if required (47a) Hotel/casino, with 330 rooms, 20 Slot machines, 20 gaming tables, Price $360m Now Sold NOW SOLD (47b) Hotel/casino, with 160 rooms, 40 Slot machines, 35 gaming tables, Price $285m/ Now sold (47c) Hotel/casino, with 360 rooms 100 Slot machines, 40 gaming tables, +5 VIPs tables, Price $350m / Now Sold (47d) Hotel/casino, with 320 rooms, 140 Slot Machines, 20 gaming tables + 15 VIPs tables Price $300m/Now Sold (47e) Hotel/casino with 450 rooms, 100 Slots Machines 50 gaming tables +15 VIPs tables Price $345m/ Now Sold Full Management facilities for casino and hotel available,', '<p>Update 24 March 2015 the last of the 5 casinos has been sold today, Macau see listing below for each hotel/casino price,but the price of the 1 remaining casino hotel for sale is now $360,000,000 US operating with profit in Macau Price $360,000,000, new funding of 75% available on this last property with Management if required</p><p>(47a)</p><p>Hotel/casino, with 330 rooms, 20 Slot machines, 20 gaming tables,</p><p> Price $360m Now Sold NOW SOLD</p><p>(47b)</p><p>Hotel/casino, with 160 rooms, 40 Slot machines, 35 gaming tables, </p><p>Price $285m/ Now sold</p><p>(47c)</p><p>Hotel/casino, with 360 rooms 100 Slot machines, 40 gaming tables, +5 VIPs tables, </p><p>Price $350m / Now Sold</p><p>(47d)</p><p>Hotel/casino, with 320 rooms, 140 Slot Machines, 20 gaming tables + 15 VIPs tables </p><p>Price $300m/Now Sold</p><p>(47e)</p><p>Hotel/casino with 450 rooms, 100 Slots Machines 50 gaming tables +15 VIPs tables </p><p>Price $345m/ Now Sold </p><p>Full Management facilities for casino and hotel available,</p>', '', '["Update 24 March 2015 the last of the 5 casinos has been sold today, Macau see listing below for each hotel/casino price,but the price of the 1 remaining casino hotel for sale is now $360,000,000 US operating with profit in Macau Price $360,000,000, new funding of 75% available on this last property with Management if required (47a) Hotel/casino, with 330 rooms, 20 Slot machines, 20 gaming tables, Price $360m Now Sold NOW SOLD (47b) Hotel/casino, with 160 rooms, 40 Slot machines, 35 gaming tables, Price $285m/ Now sold (47c) Hotel/casino, with 360 rooms 100 Slot machines, 40 gaming tables, +5 VIPs tables, Price $350m / Now Sold (47d) Hotel/casino, with 320 rooms, 140 Slot Machines, 20 gaming tables + 15 VIPs tables Price $300m/Now Sold (47e) Hotel/casino with 450 rooms, 100 Slots Machines 50 gaming tables +15 VIPs tables Price $345m/ Now Sold Full Management facilities for casino and hotel available,"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
