INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-41', '41', 'listing-41', 'Listing 41', NULL, 'casino', '$500,000', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Update February 2015 Now Sold Ghana update 19th December 2014 this casino has been closed due to a disagreement between the partners and all the slots and tables have been removed but is now being sold as-is could be open in 24 hours with your own equipment at the reduced price of $500,000 All new casino less than 12 months old, with a fine dining restaurant, stage for live music and cabaret, 11 live gaming tables with roulette blackjack, stud poker, and Texas hold ’em, and 50 slot machines.', '<p>Update February 2015 Now Sold Ghana update 19th December 2014 this casino has been closed due to a disagreement between the partners and all the slots and tables have been removed but is now being sold as-is could be open in 24 hours with your own equipment at the reduced price of $500,000 All new casino less than 12 months old, with a fine dining restaurant, stage for live music and cabaret, 11 live gaming tables with roulette blackjack, stud poker, and Texas hold ’em, and 50 slot machines. with a sports betting licence included in the price</p><p>$2.500.000 now sold</p>', '', '["Update February 2015 Now Sold Ghana update 19th December 2014 this casino has been closed due to a disagreement between the partners and all the slots and tables have been removed but is now being sold as-is could be open in 24 hours with your own equipment at the reduced price of $500,000 All new casino less than 12 months old, with a fine dining restaurant, stage for live music and cabaret, 11 live gaming tables with roulette blackjack, stud poker, and Texas hold ’em, and 50 slot machines.","with a sports betting licence included in the price $2.500.000 now sold"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-40', '40', 'listing-40', 'Listing 40', 'Czech Republic', 'casino', '4,500,000 Euros', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'New Update January 2017 now sold German Border, Czech Republic well-established Casino open 10 years with good profits, 95% German clients, Smoking is allowed in this casino, The casino property has large grounds with parking for 200 cars and is being sold freehold with a 50 bedroom hotel 4 minutes by car from the Casino but the hotel is closed and would need to be completely refurbished but it is believed this is an easy and quick property to transform but no costings have been made for this work, Great casino floor with a total of 24 gaming tables, and over 90 slot machines 12 poker tables,3 Blackjack tables,4 Ameican Roulette tables, 8 base touch bet roulette machine 2 Restaurants , one is a VIP, plus 2 Cocktails bars, hotel pick up coach, Open hours 2pm to 5am, Price 4,500,000 Euros includes everything or a joint venture could be possible with the casino manager on a 50/50 share basis,', '<p>New Update January 2017 now sold  German Border, Czech Republic well-established Casino open 10 years with good profits, 95% German clients, Smoking is allowed in this casino, The casino property has large grounds with parking for 200 cars and is being sold freehold with a 50 bedroom hotel 4 minutes by car from the Casino but the hotel is closed and would need to be completely refurbished but it is believed this is an easy and quick property to transform but no costings have been made for this work, Great casino floor with a total of 24 gaming tables, and over 90 slot machines 12 poker tables,3 Blackjack tables,4 Ameican Roulette tables, 8 base touch bet roulette machine 2 Restaurants , one is a VIP, plus 2 Cocktails bars, hotel pick up coach, Open hours 2pm to 5am, Price 4,500,000 Euros includes everything or a joint venture could be possible with the casino manager on a 50/50 share basis,</p>', '', '["New Update January 2017 now sold German Border, Czech Republic well-established Casino open 10 years with good profits, 95% German clients, Smoking is allowed in this casino, The casino property has large grounds with parking for 200 cars and is being sold freehold with a 50 bedroom hotel 4 minutes by car from the Casino but the hotel is closed and would need to be completely refurbished but it is believed this is an easy and quick property to transform but no costings have been made for this work, Great casino floor with a total of 24 gaming tables, and over 90 slot machines 12 poker tables,3 Blackjack tables,4 Ameican Roulette tables, 8 base touch bet roulette machine 2 Restaurants , one is a VIP, plus 2 Cocktails bars, hotel pick up coach, Open hours 2pm to 5am, Price 4,500,000 Euros includes everything or a joint venture could be possible with the casino manager on a 50/50 share basis,"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
