INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-26', '26', 'listing-26', 'Listing 26', NULL, 'casino', '$4,500,000', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Update MAY 2016, Price reduced to $4,500,000 Now sold the Dominican Republic, Great opportunity to buy a large luxury casino with 2000 sq ft spread over 3 levels within a 4 star hotel, the casino which is on lease for 10 years has 200 slot machines 13 gaming tables A/R,B/J,Punto Banco, Craps, Texas Holden, large bar lounge, Also a VIP Salon with 10 Slots 4 gaming tables, good profits, Price for Casino only $5.000,000 now reduced to $4,500,000 now sold', '<p>Update MAY 2016, Price reduced to $4,500,000 Now sold the Dominican Republic, Great opportunity to buy a large luxury casino with 2000 sq ft spread over 3 levels within a 4 star hotel, the casino which is on lease for 10 years has 200 slot machines 13 gaming tables A/R,B/J,Punto Banco, Craps, Texas Holden, large bar lounge, Also a VIP Salon with 10 Slots 4 gaming tables, good profits, Price for Casino only $5.000,000 now reduced to $4,500,000 now sold</p>', '', '["Update MAY 2016, Price reduced to $4,500,000 Now sold the Dominican Republic, Great opportunity to buy a large luxury casino with 2000 sq ft spread over 3 levels within a 4 star hotel, the casino which is on lease for 10 years has 200 slot machines 13 gaming tables A/R,B/J,Punto Banco, Craps, Texas Holden, large bar lounge, Also a VIP Salon with 10 Slots 4 gaming tables, good profits, Price for Casino only $5.000,000 now reduced to $4,500,000 now sold"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_s