asino poker, Punto/Banco, all applications have been approved including a licensed fine dining Restaurant, it is now also possible to lease the complete property and permits on a 5/7 year lease at 30,000 Euros per month, Or the asking price for the freehold including permits 10m Euros."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
