INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-18', '18', 'listing-18', 'Listing 18', 'Czech Republic', 'casino', '2,000 euros', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Updated March 2017 Now Sold Czech Republic Great opportunity to buy your own operating casino on low entrance money Very Smart stand-alone Casino on the German border with 5 live-gaming tables, Roulette, Blackjack, poker, this part of the Live Casino has been closed due to the illness of the casino manager, and this is the only reason for the sale of the casino, But downstairs the casino multi-bet roulette 10 seater is open downstairs with over 25 Slot Machines and a smart bar and snacks and a cocktail bar, the casino has a full 20 camera security system, all equipment was new one year ago,property is on lease at a very low rental of only 2,000 euros a month, total Price to move in and includes all the equipment, gaming tables everything as is the potential is incredible and this is a real bargain for only 499,500 Euros Now Sold', '<p>Updated March 2017 Now Sold Czech Republic Great opportunity to buy your own operating casino on low entrance money Very Smart stand-alone Casino on the German border with 5 live-gaming tables, Roulette, Blackjack, poker, this part of the Live Casino has been closed due to the illness of the casino manager, and this is the only reason for the sale of the casino, But downstairs the casino multi-bet roulette 10 seater is open downstairs with over 25 Slot Machines and a smart bar and snacks and a cocktail bar, the casino has a full 20 camera security system, all equipment was new one year ago,property is on lease at a very low rental of only 2,000 euros a month, total Price to move in and includes all the equipment, gaming tables everything as is the potential is incredible and this is a real bargain for only 499,500 Euros Now Sold</p>', '', '["Updated March 2017 Now Sold Czech Republic Great opportunity to buy your own operating casino on low entrance money Very Smart stand-alone Casino on the German border with 5 live-gaming tables, Roulette, Blackjack, poker, this part of the Live Casino has been closed due to the illness of the casino manager, and this is the only reason for the sale of the casino, But downstairs the casino multi-bet roulette 10 seater is open downstairs with over 25 Slot Machines and a smart bar and snacks and a cocktail bar, the casino has a full 20 camera security system, all equipment was new one year ago,property is on lease at a very low rental of only 2,000 euros a month, total Price to move in and includes all the equipment, gaming tables everything as is the potential is incredible and this is a real bargain for only 499,500 Euros Now Sold"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-17', '17', 'listing-17', 'Listing 17', 'Czech Republic', 'casino', '550,000 Euros', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Update February 2015 Czech Republic this property was sold on the 30th January 2014 For sale a very busy Casino on the German Border,within a Wonderfull Old world type Hotel property on 3 floors with 25 bedrooms, restaurants which also has entrance from street level, This very large ground floor casino, with Slots, Roulette, Blackjack, Poker, all popular table games Owner retiring bargain Price1.550,000 Euros includes the casino business and all casinos equipment, The casino licence is leased with 9 years left to run,rental is 4,000 euros per month, also the casino space is leased from the hotel with 9 years to run at a rental of 4,500 euros per month Now Sold', '<p>Update February 2015 Czech Republic this property was sold on the 30th January 2014 For sale a very busy Casino on the German Border,within a Wonderfull Old world type Hotel property on 3 floors with 25 bedrooms, restaurants which also has entrance from street level, This very large ground floor casino, with Slots, Roulette, Blackjack, Poker, all popular table games Owner retiring bargain Price1.550,000 Euros includes the casino business and all casinos equipment, The casino licence is leased with 9 years left to run,rental is 4,000 euros per month, also the casino space is leased from the hotel with 9 years to run at a rental of 4,500 euros per month Now Sold</p>', '', '["Update February 2015 Czech Republic this property was sold on the 30th January 2014 For sale a very busy Casino on the German Border,within a Wonderfull Old world type Hotel property on 3 floors with 25 bedrooms, restaurants which also has entrance from street level, This very large ground floor casino, with Slots, Roulette, Blackjack, Poker, all popular table games Owner retiring bargain Price1.550,000 Euros includes the casino business and all casinos equipment, The casino licence is leased with 9 years left to run,rental is 4,000 euros per month, also the casino space is leased from the hotel with 9 years to run at a rental of 4,500 euros per month Now Sold"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-16', '16', 'listing-16', 'Listing 16', 'Cyprus', 'casino', '30m EUROS', 'draft', 'pending', 'OPPORTUNITY', 'New update July 2016 now Cancelled biding time already passed, Cyprus with new laws coming into force to allow casinos in the Southern part of Cyprus, cancelled now only one licence being granted, with 5 star hotel only, This makes this a great opportunity Possible JV The casino license has been verbally granted on conditions the applicant has at least 3 years casino operational experience, and the hotel property which is now a 3 star must be converted with a grand refurbishment to a 5 star standard hotel and the casino will be allowed to be installed within the hotel property, The Hotel owner is looking for partners or investors to complete the upgrade and partners to take over both management of hotel plus or Casino only, The new hotel and casino resort will have a total ground area of 20,000 Sq meters, total investment cost to upgrade this closed hotel property is approx 30-40m euros but the owner is willing to put up the land to start building as a 50% joint venture partnership in the profits,or will sell out the complete property as is for 30m EUROS Now Cancelled', '<p>New update July 2016 now Cancelled biding time already passed, Cyprus with new laws coming into force to allow casinos in the Southern part of Cyprus, cancelled now <strong>only one licence being granted, </strong>with 5 star hotel only, This makes this a great opportunity Possible JV The casino license has been verbally granted on conditions the applicant has at least 3 years casino operational experience, and the hotel property which is now a 3 star must be converted with a grand refurbishment to a 5 star standard hotel and the casino will be allowed to be installed within the hotel property, The Hotel owner is looking for partners or investors to complete the upgrade and partners to take over both management of hotel plus or Casino only, The new hotel and casino resort will have a total ground area of 20,000 Sq meters, total investment cost to upgrade this closed hotel property is approx 30-40m euros but the owner is willing to put up the land to start building as a 50% joint venture partnership in the profits,or will sell out the complete property as is for 30m EUROS Now Cancelled</p>', '', '["New update July 2016 now Cancelled biding time already passed, Cyprus with new laws coming into force to allow casinos in the Southern part of Cyprus, cancelled now only one licence being granted, with 5 star hotel only, This makes this a great opportunity Possible JV The casino license has been verbally granted on conditions the applicant has at least 3 years casino operational experience, and the hotel property which is now a 3 star must be converted with a grand refurbishment to a 5 star standard hotel and the casino will be allowed to be installed within the hotel property, The Hotel owner is looking for partners or investors to complete the upgrade and partners to take over both management of hotel plus or Casino only, The new hotel and casino resort will have a total ground area of 20,000 Sq meters, total investment cost to upgrade this closed hotel property is approx 30-40m euros but the owner is willing to put up the land to start building as a 50% joint venture partnership in the profits,or will sell out the complete property as is for 30m EUROS Now Cancelled"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=ex