INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-12', '12', 'listing-12', 'Listing 12', 'Costa Rica', 'casino', '$60m', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Updated March 2016 owners received an offer, will advise, UPdate 3rd January 2017 Costa Rica now been sold 4 Casinos within 4 good 3/4 star hotels one hotel has 200 rooms, 3 of the casinos have A/R, B/J, 220 Slot machines, the other one casino is a slots palace only with 0ver 400 slots, Total of 621 gaming slots Plus 9 gaming tables included in this total package price is 2 new internet casino Sportbetting Licences ready to go online with your own brand platform Good profits in all departments,, Two Options, 1,To buy/lease all 4 casinos and one hotel $15m, with owner funding 2, To buy outright all 4 casinos, all 3 hotels, including the two new online Gaming Licences, sale price $60m with seller finance Now Sold', '<p>Updated March 2016 owners received an offer, will advise, UPdate 3rd January 2017 <strong>Costa Rica now been sold 4 Casinos within 4 good 3/4 star hotels one hotel has 200 rooms, 3 of the casinos have A/R, B/J, 220 Slot machines, the other one casino is a slots palace only with 0ver 400 slots, Total of 621 gaming slots Plus 9 gaming tables included in this total package price is 2 new internet casino Sportbetting Licences ready to go online with your own brand platform Good profits in all departments,, Two Options, 1,To buy/lease all 4 casinos and one hotel $15m, with owner funding 2, To buy outright all 4 casinos, all 3 hotels, including the two new online Gaming Licences, sale price $60m with seller finance Now Sold</strong></p>', '', '["Updated March 2016 owners received an offer, will advise, UPdate 3rd January 2017 Costa Rica now been sold 4 Casinos within 4 good 3/4 star hotels one hotel has 200 rooms, 3 of the casinos have A/R, B/J, 220 Slot machines, the other one casino is a slots palace only with 0ver 400 slots, Total of 621 gaming slots Plus 9 gaming tables included in this total package price is 2 new internet casino Sportbetting Licences ready to go online with your own brand platform Good profits in all departments,, Two Options, 1,To buy/lease all 4 casinos and one hotel $15m, with owner funding 2, To buy outright all 4 casinos, all 3 hotels, including the two new online Gaming Licences, sale price $60m with seller finance Now Sold"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
