INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-8', '8', 'listing-8', 'Listing 8', 'Croatia', 'casino', '25M EUROS', 'draft', 'pending', 'OPPORTUNITY', 'Croatia Update 2nd March 2016 This Property is back on the market at a reduced price for sale at 25M EUROS but Casino is closed This 300 room 4-star hotel and casinos are right in the centre of the most popular tourist area, with rooms having beach and sea views The 50 room extension or condos have now been completed, The Casino has a 10-month casino business with 11 gaming tables 6 roulette 3 blackjack, and 2 casino poker, plus 60 slot machines and one automatic roulette 8 seaters, just opened a restaurant gaming terrace with 3 gaming tables the casino this could be improved by Junket players, Now priced to sell with a 5,000,000 euro down payment the casino will be reopened, The balance of 21,000,000 euros is by way of a Bank mortgage which the new owner will take over, great potential opportunity', '<p>Croatia Update 2nd March 2016 This Property is back on the market at a reduced price for sale at 25M EUROS but Casino is closed This 300 room 4-star hotel and casinos are right in the centre of the most popular tourist area, with rooms having beach and sea views</p><p>The 50 room extension or condos have now been completed,</p><p>The Casino has a 10-month casino business with 11 gaming tables 6 roulette 3 blackjack, and 2 casino poker, plus 60 slot machines and one automatic roulette 8 seaters, just opened a restaurant gaming terrace with 3 gaming tables the casino this could be improved by Junket players,</p><p>Now priced to sell with a 5,000,000 euro down payment the casino will be reopened,</p><p>The balance of 21,000,000 euros is by way of a Bank mortgage which the new owner will take over, great potential opportunity</p>', '', '["Croatia Update 2nd March 2016 This Property is back on the market at a reduced price for sale at 25M EUROS but Casino is closed This 300 room 4-star hotel and casinos are right in the centre of the most popular tourist area, with rooms having beach and sea views The 50 room extension or condos have now been completed, The Casino has a 10-month casino business with 11 gaming tables 6 roulette 3 blackjack, and 2 casino poker, plus 60 slot machines and one automatic roulette 8 seaters, just opened a restaurant gaming terrace with 3 gaming tables the casino this could be improved by Junket players, Now priced to sell with a 5,000,000 euro down payment the casino will be reopened, The balance of 21,000,000 euros is by way of a Bank mortgage which the new owner will take over, great potential opportunity"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
INSERT INTO opportunities (id, legacy_id, slug, title, country, opportunity_type, price_text, lifecycle, content_review_status, legacy_status, summary, body_html, availability, points_json, public_visibility, created_at, updated_at) VALUES ('legacy-7', '7', 'listing-7', 'Listing 7', 'Croatia', 'casino', '67m euros', 'sold', 'pending', 'SOLD / STATUS UPDATE', 'Updated 10th Sept 2014 this property is now on hold no more enquiries please at the moment, Croatia Rivera, This multiple award-winning luxury 5-star beach hotel, with an approx 400 sea view rooms and elegant suites, overlooking the 75 berth yacht Marina.', '<p>Updated 10th Sept 2014 this property is now on hold no more enquiries please at the moment, Croatia Rivera, This multiple award-winning luxury 5-star beach hotel, with an approx 400 sea view rooms and elegant suites, overlooking the 75 berth yacht Marina. With one of the largest Conference Centres in Europe with a total seating capacity for 1,500 persons. An exciting nightclub, disco dancing and cabaret, One fine dining Restaurant, Cafes, Italian Pizzeria, Large Gymnasium with the latest Equipment and luxury Beauty Spa, Indoor and Outdoor Swimming pools. Plus a very popular 24/7 intimate coffee bar A Grand Casino, with a Prive Salon, one of the largest casinos in Croatia with 60 of the latest slot machines, 17 gaming tables, American Roulette, Blackjack, etc, Now with a new poker area with 5 poker tables for cash games and Poker Tournaments.Please note the Casino is now closed but can be reopened with the new owner in a very short time, This multi casino license permits the opening of more casinos in Croatia This International flagged hotel/resort complex is being sold as a fully operational, and Managed Business, With an asking price of 67m euros, downpayment of 55m euros and the balance of 12m Euros payable over 2 years, the owner may consider a Joint venture, The hotel property had its best 3rd quarter for 3 years,</p>', '', '["Updated 10th Sept 2014 this property is now on hold no more enquiries please at the moment, Croatia Rivera, This multiple award-winning luxury 5-star beach hotel, with an approx 400 sea view rooms and elegant suites, overlooking the 75 berth yacht Marina.","With one of the largest Conference Centres in Europe with a total seating capacity for 1,500 persons.","An exciting nightclub, disco dancing and cabaret, One fine dining Restaurant, Cafes, Italian Pizzeria, Large Gymnasium with the latest Equipment and luxury Beauty Spa, Indoor and Outdoor Swimming pools."]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
