hotel properties, With new criteria, proof of funds are no longer required,?","but new Criteria you have to provide the 5% into Escrow as your part of the investment into your purchase, only for the purchase of casino properties from Casinos of Mayfair which are listed on this and other websites of COM, the 5% will be refunded should the fund not be available to you,"]', 0, '2026-10-09T13:47:48.200Z', '2026-10-09T13:47:48.200Z') ON CONFLICT(legacy_id) DO UPDATE SET title=excluded.title, country=excluded.country, price_text=excluded.price_text, lifecycle=excluded.lifecycle, content_review_status='pending', legacy_status=excluded.legacy_status, summary=excluded.summary, body_html=excluded.body_html, availability=excluded.availability, points_json=excluded.points_json, public_visibility=0, updated_at=excluded.updated_at;
